1|// Client driver for POST /api/uploads plus the step loop. The key and
2|// the human token arrive as arguments and stay in memory; nothing here
3|// touches storage, logs, or the URL.
4|import { BYOK_HEADER } from "@/core/chat";
5|import type { RawSection } from "@/core/clean-types";
6|import { isUploadId, UPLOAD_MESSAGES, type UploadErrorCode } from "@/core/uploads";
7|
8|export type FlowCode = UploadErrorCode | "network";
9|
10|export const STEP_RETRIES = 3;
11|const BACKOFF_MS = [500, 1000, 2000];
12|
13|export interface FlowProgress {
14|  jobId: string;
15|  done: number;
16|  total: number;
17|  chapters: number;
18|}
19|
20|export interface DriveOpts {
21|  title: string;
22|  author: string | null;
23|  sections: RawSection[];
24|  key: string | null;
25|  token: string | null;
26|  friendCode?: string | null;
27|  jobId: string | null;
28|  fetchFn?: typeof fetch;
29|  sleep?: (ms: number) => Promise<void>;
30|  signal?: AbortSignal;
31|  onProgress?: (progress: FlowProgress) => void;
32|}
33|
34|export class UploadFlowError extends Error {
35|  code: FlowCode;
36|  jobId: string | null;
37|  constructor(code: FlowCode, jobId: string | null) {
38|    super(code);
39|    this.name = "UploadFlowError";
40|    this.code = code;
41|    this.jobId = jobId;
42|  }
43|}
44|
45|function isCode(value: unknown): value is UploadErrorCode {
46|  return typeof value === "string" && value in UPLOAD_MESSAGES;
47|}
48|
49|function isCount(value: unknown): value is number {
50|  return typeof value === "number" && Number.isInteger(value) && value >= 0;
51|}
52|
53|async function readJson(res: Response): Promise<unknown> {
54|  try {
55|    return (await res.json()) as unknown;
56|  } catch {
57|    return null;
58|  }
59|}
60|
61|function defaultSleep(ms: number, signal?: AbortSignal): Promise<void> {
62|  return new Promise((resolve, reject) => {
63|    const timer = setTimeout(() => {
64|      signal?.removeEventListener("abort", onAbort);
65|      resolve();
66|    }, ms);
67|    const onAbort = (): void => {
68|      clearTimeout(timer);
69|      reject(signal?.reason ?? new Error("aborted"));
70|    };
71|    if (signal?.aborted) {
72|      onAbort();
73|      return;
74|    }
75|    signal?.addEventListener("abort", onAbort, { once: true });
76|  });
77|}
78|
79|function headersFor(key: string | null): Record<string, string> {
80|  return {
81|    "content-type": "application/json",
82|    ...(key ? { [BYOK_HEADER]: key } : {}),
83|  };
84|}
85|
86|interface StepOutcome {
87|  done: boolean;
88|  progress: FlowProgress;
89|}
90|
91|// One step attempt: coded errors surface at once (the UI maps them to
92|// the BYOK step or a retry note); only network failures and uncoded
93|// 5xx responses come back as retryable.
94|async function attemptStep(
95|  opts: DriveOpts,
96|  jobId: string,
97|  token: string | null,
98|  chapters: number,
99|): Promise<StepOutcome> {
100|  const fetchFn = opts.fetchFn ?? fetch;
101|  let res: Response;
102|  try {
103|    res = await fetchFn(`/api/uploads/${jobId}/step`, {
104|      method: "POST",
105|      headers: headersFor(opts.key),
106|      body: JSON.stringify(token ? { turnstileToken: token } : {}),
107|      signal: opts.signal,
108|    });
109|  } catch (err) {
110|    if (opts.signal?.aborted) throw err;
111|    throw new UploadFlowError("network", jobId);
112|  }
113|  const json = await readJson(res);
114|  const body = (typeof json === "object" && json !== null ? json : {}) as Record<string, unknown>;
115|  if (body.status === "error" && isCode(body.code)) {
116|    throw new UploadFlowError(body.code, jobId);
117|  }
118|  if (res.status >= 500) throw new UploadFlowError("network", jobId);
119|  if ((body.status === "working" || body.status === "done") && isCount(body.done) && isCount(body.total)) {
120|    const progress = { jobId, done: body.done, total: body.total, chapters };
121|    return { done: body.status === "done", progress };
122|  }
123|  if (body.status === "error") throw new UploadFlowError("bad_request", jobId);
124|  throw new UploadFlowError("unavailable", jobId);
125|}
126|
127|// Drives create (once: every attempt can take quota) then steps until
128|// done. Resuming reuses the job id, so progress continues from the
129|// server's done/total. Steps retry network failures and uncoded 5xx.
130|export async function driveUpload(opts: DriveOpts): Promise<{ id: string; chapters: number }> {
131|  const fetchFn = opts.fetchFn ?? fetch;
132|  const sleep = opts.sleep ?? ((ms: number) => defaultSleep(ms, opts.signal));
133|  let token = opts.token;
134|  let jobId = opts.jobId;
135|  let chapters = 0;
136|  if (!jobId) {
137|    let res: Response;
138|    try {
139|      res = await fetchFn("/api/uploads", {
140|        method: "POST",
141|        headers: headersFor(opts.key),
142|        body: JSON.stringify({
143|          title: opts.title,
144|          author: opts.author,
145|          sections: opts.sections,
146|          ...(token ? { turnstileToken: token } : {}),
147|          ...(opts.friendCode ? { friendCode: opts.friendCode } : {}),
148|        }),
149|        signal: opts.signal,
150|      });
151|    } catch (err) {
152|      if (opts.signal?.aborted) throw err;
153|      throw new UploadFlowError("network", null);
154|    }
155|    token = null; // Single use: later steps ride the human cookie. secret-scan:allow (not a secret)
156|    const json = await readJson(res);
157|    const body = (typeof json === "object" && json !== null ? json : {}) as Record<string, unknown>;
158|    if (body.status === "error" && isCode(body.code)) throw new UploadFlowError(body.code, null);
159|    if (
160|      body.status !== "created" ||
161|      !isUploadId(body.id) ||
162|      !isCount(body.chapters) ||
163|      !isCount(body.parts)
164|    ) {
165|      throw new UploadFlowError("unavailable", null);
166|    }
167|    jobId = body.id;
168|    chapters = body.chapters;
169|    opts.onProgress?.({ jobId, done: 0, total: body.parts, chapters });
170|  }
171|  for (;;) {
172|    let attempt = 0;
173|    for (;;) {
174|      try {
175|        const outcome = await attemptStep(opts, jobId, token, chapters);
176|        token = null;
177|        opts.onProgress?.(outcome.progress);
178|        if (outcome.done) return { id: jobId, chapters };
179|        break;
180|      } catch (err) {
181|        if (opts.signal?.aborted) throw err;
182|        // Only the retryable shape loops; coded errors fail at once.
183|        const retryable = err instanceof UploadFlowError && err.code === "network";
184|        if (!retryable || attempt >= STEP_RETRIES) throw err;
185|        await sleep(BACKOFF_MS[attempt] ?? 2000);
186|        attempt += 1;
187|      }
188|    }
189|  }
190|}

