40|function progressCopy(progress: FlowProgress | null): string {
41|  if (!progress) return "Reading your book…";
42|  if (progress.total > 0 && progress.done >= progress.total) return "Setting it to music…";
43|  if (progress.done <= 0) return "Finding the scenes…";
44|  return `Listening for the mood of chapter ${progress.done + 1} of ${progress.total}…`;
