104|  // eslint-disable-next-line react-hooks/set-state-in-effect -- mount-only free-book count from localStorage after hydration
105|  useEffect(() => setFreeCount(getFreeBooksToday()), []);
106|  useEffect(() => () => abortRef.current?.abort(), []);
107|
108|  // The result views replace the drop zone, so move focus into the
109|  // result; otherwise keyboard focus is lost when it unmounts.
110|  useEffect(() => {
111|    if (status.step !== "idle" && status.step !== "reading" && status.step !== "error") {
112|      resultRef.current?.focus();
113|    }
114|  }, [status]);
115|
116|  const parsed =
117|    status.step === "parsed" ||
118|    status.step === "working" ||
119|    status.step === "finishing" ||
120|    status.step === "failed"
121|      ? status.parsed
122|      : null;
123|  const book = parsed?.book ?? null;
