1|// Client driver for POST /api/uploads plus the step loop. The key and
2|// the human token arrive as arguments and stay in memory; nothing here
3|// touches storage, logs, or the URL.
4|import { BYOK_HEADER } from "@/core/chat";
5|import type { RawSection } from "@/core/clean-types";
6|import { isUploadId, UPLOAD_MESSAGES, type UploadErrorCode } from "@/core/uploads";
7|
8|export type FlowCode = UploadErrorCode | "network";
9|
10|export const STEP_RETRIES = 3;
11|const BACKOFF_MS = [500, 1000, 2000];
12|
13|export interface FlowProgress {
14|  jobId: string;
15|  done: number;
16|  total: number;
17|  chapters: number;
18|}
19|
20|export interface DriveOpts {
21|  title: string;
22|  author: string | null;
23|  sections: RawSection[];
24|  key: string | null;
25|  token: string | null;
26|  friendCode?: string | null;
27|  jobId: string | null;
28|  fetchFn?: typeof fetch;
29|  sleep?: (ms: number) => Promise<void>;
30|  signal?: AbortSignal;
31|  onProgress?: (progress: FlowProgress) => void;
32|}
33|
34|export class UploadFlowError extends Error {
35|  code: FlowCode;
36|  jobId: string | null;
37|  constructor(code: FlowCode, jobId: string | null) {
38|    super(code);
39|    this.name = "UploadFlowError";
40|    this.code = code;
41|    this.jobId = jobId;
42|  }
43|}
44|
45|function isCode(value: unknown): value is UploadErrorCode {
46|  return typeof value === "string" && value in UPLOAD_MESSAGES;
47|}
48|
49|function isCount(value: unknown): value is number {
50|  return typeof value === "number" && Number.isInteger(value) && value >= 0;
51|}
52|
53|async function readJson(res: Response): Promise<unknown> {
54|  try {
55|    return (await res.json()) as unknown;
56|  } catch {
57|    return null;
58|  }
59|}
60|
61|function defaultSleep(ms: number, signal?: AbortSignal): Promise<void> {
62|  return new Promise((resolve, reject) => {
63|    const timer = setTimeout(() => {
64|      signal?.removeEventListener("abort", onAbort);
65|      resolve();
66|    }, ms);
67|    const onAbort = (): void => {
68|      clearTimeout(timer);
69|      reject(signal?.reason ?? new Error("aborted"));
70|    };
71|    if (signal?.aborted) {
72|      onAbort();
73|      return;
74|    }
75|    signal?.addEventListener("abort", onAbort, { once: true });
76|  });
77|}
78|
79|function headersFor(key: string | null): Record<string, string> {
80|  return {
81|    "content-type": "application/json",
82|    ...(key ? { [BYOK_HEADER]: key } : {}),
83|  };
84|}
